function fmt(n){if(!Number.isFinite(n))return String(n);if(Math.abs(n)<1e-12)return '0';return Number(n.toPrecision(10)).toString()}
function num(id){const v=Number($(id).value);if($(id).value.trim()===''||!Number.isFinite(v))throw new Error('請輸入有效的數字。');return v}
