function safeEval(expression, xValue=null){
  let s=String(expression).trim().replace(/×/g,'*').replace(/÷/g,'/').replace(/π/g,'pi').replace(/\^/g,'**');
  if(!s)throw new Error('請先輸入計算式。');
  if(s.length>180)throw new Error('輸入內容太長。');
  // Implicit multiplication for common classroom notation.
  s=s.replace(/(\d)(x|pi|e\b|sqrt|sin|cos|tan|abs|log|ln|exp)\b/g,'$1*$2').replace(/\)(x|pi|e\b|sqrt|sin|cos|tan|abs|log|ln|exp)\b/g,')*$1');
  const allowed=/^[0-9+\-*/().,\s%a-zA-Z_]*$/;
  if(!allowed.test(s))throw new Error('包含不支援的字元。');
  const names=['sin','cos','tan','asin','acos','atan','sqrt','abs','log','ln','exp','floor','ceil','round'];
  for(const name of names){const re=new RegExp('\\b'+name+'\\s*\\(','g');s=s.replace(re,`__${name}(`)}
  // Replace function calls with an allow-listed math object; no eval or Function constructor.
  const fnMap={sin:Math.sin,cos:Math.cos,tan:Math.tan,asin:Math.asin,acos:Math.acos,atan:Math.atan,sqrt:Math.sqrt,abs:Math.abs,log:Math.log10,ln:Math.log,exp:Math.exp,floor:Math.floor,ceil:Math.ceil,round:Math.round};
  // A tiny recursive-descent parser avoids executing user-entered JavaScript.
  let i=0;
  const tokenRe=/\s*(?:(\d+(?:\.\d*)?|\.\d+)(?:([eE][+-]?\d+))?|([A-Za-z_][A-Za-z_0-9]*)|(\*\*|[+\-*/^()%!,]))/y;
  const tokens=[];while(i<s.length){tokenRe.lastIndex=i;const m=tokenRe.exec(s);if(!m)throw new Error('無法辨識的符號：'+s.slice(i,i+8));i=tokenRe.lastIndex;if(m[1]!==undefined)tokens.push({t:'num',v:Number(m[1]+(m[2]||''))});else if(m[3])tokens.push({t:'id',v:m[3]});else tokens.push({t:m[4],v:m[4]})}
  let p=0;const peek=()=>tokens[p]||{t:'eof'};const take=()=>tokens[p++];
  function primary(){let t=take();if(t.t==='num')return t.v;if(t.t==='+'||t.t==='-'){const v=primary();return t.t==='-'?-v:v}if(t.t==='('){const v=add();if(take().t!==')')throw new Error('括號不完整。');return v}if(t.t==='id'){if(t.v==='x'&&xValue!==null)return xValue;if(t.v==='pi'||t.v==='Math.PI')return Math.PI;if(t.v==='e'||t.v==='Math.E')return Math.E;if(t.v.startsWith('__')){const name=t.v.slice(2);if(!fnMap[name])throw new Error('不支援的函數：'+name);if(take().t!=='(')throw new Error('函數後面需要括號。');const v=add();if(take().t!==')')throw new Error('函數括號不完整。');let arg=v;if(['sin','cos','tan'].includes(name)&&angleMode==='DEG')arg=v*Math.PI/180;const out=fnMap[name](arg);return ['asin','acos','atan'].includes(name)&&angleMode==='DEG'?out*180/Math.PI:out}throw new Error('不支援的變數：'+t.v)}throw new Error('運算式格式不正確。')}
  function fact(v){if(peek().t==='!'){take();if(!Number.isInteger(v)||v<0||v>170)throw new Error('階乘只支援 0 到 170 的整數。');let r=1;for(let k=2;k<=v;k++)r*=k;return r}return v}
  function power(){let v=fact(primary());if(peek().t==='^'||peek().t==='**'){take();v=Math.pow(v,power())}return v}
  function mul(){let v=power();while(['*','/','%'].includes(peek().t)){const op=take().t,b=power();if(op==='*')v*=b;else if(op==='/')v/=b;else v%=b}return v}
  function add(){let v=mul();while(peek().t==='+'||peek().t==='-'){const op=take().t,b=mul();v=op==='+'?v+b:v-b}return v}
  const result=add();if(p<tokens.length)throw new Error('運算式格式不完整。');if(!Number.isFinite(result))throw new Error('結果不是有限數值，請檢查輸入。');return result;
}
function calcRun(){try{const expr=$('calcInput').value;const result=safeEval(expr);$('calcExpression').textContent=expr;$('calcResult').textContent=fmt(result);saveHistory('科學計算機',expr,fmt(result))}catch(e){$('calcResult').textContent='錯誤';$('calcExpression').textContent=e.message;toast(e.message)}}
$('angleMode').addEventListener('click',()=>{angleMode=angleMode==='DEG'?'RAD':'DEG';$('angleModeLabel').textContent=angleMode;$('angleMode').textContent='切換 '+(angleMode==='DEG'?'RAD':'DEG');toast('已切換為 '+angleMode)});
$('calcKeypad').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const act=b.dataset.action;if(act==='clear'){$('calcInput').value='';$('calcResult').textContent='0';$('calcExpression').textContent='準備開始'}else if(act==='backspace'){$('calcInput').value=$('calcInput').value.slice(0,-1)}else if(act==='calculate')calcRun();else{$('calcInput').value+=b.dataset.insert;$('calcInput').focus()}});
$('calcInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();calcRun()}});
function drawGraph(){const canvas=$('graphCanvas');if(!canvas)return;const rect=canvas.getBoundingClientRect();if(!rect.width)return;const dpr=window.devicePixelRatio||1;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.width*.62*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const W=rect.width,H=rect.width*.62;const xmin=Number($('xMin').value),xmax=Number($('xMax').value),ymin=Number($('yMin').value),ymax=Number($('yMax').value);ctx.clearRect(0,0,W,H);ctx.fillStyle=getComputedStyle(document.body).getPropertyValue('--surface').trim()||'#fff';ctx.fillRect(0,0,W,H);if(!(xmax>xmin&&ymax>ymin)){ $('graphStatus').textContent='座標範圍無效';return}const X=x=>((x-xmin)/(xmax-xmin))*W,Y=y=>H-((y-ymin)/(ymax-ymin))*H;ctx.lineWidth=1;ctx.strokeStyle=document.body.classList.contains('dark')?'#343953':'#e8eaf4';for(let k=Math.ceil(xmin);k<=xmax;k++){ctx.beginPath();ctx.moveTo(X(k),0);ctx.lineTo(X(k),H);ctx.stroke()}for(let k=Math.ceil(ymin);k<=ymax;k++){ctx.beginPath();ctx.moveTo(0,Y(k));ctx.lineTo(W,Y(k));ctx.stroke()}ctx.strokeStyle=document.body.classList.contains('dark')?'#9299ba':'#aab0c6';ctx.lineWidth=1.5;if(xmin<=0&&xmax>=0){ctx.beginPath();ctx.moveTo(X(0),0);ctx.lineTo(X(0),H);ctx.stroke()}if(ymin<=0&&ymax>=0){ctx.beginPath();ctx.moveTo(0,Y(0));ctx.lineTo(W,Y(0));ctx.stroke()}const expressions=[$('functionA').value.trim(),$('functionB').value.trim()];const colors=['#7968ed','#ff9d54'];let errors=[];expressions.forEach((expr,idx)=>{if(!expr)return;ctx.beginPath();ctx.strokeStyle=colors[idx];ctx.lineWidth=2.5;let started=false;for(let px=0;px<=W;px+=1.5){const x=xmin+px/W*(xmax-xmin);let y;try{y=safeEval(expr,x)}catch(e){errors.push(e.message);break}const py=Y(y);if(!Number.isFinite(py)||py<-H*5||py>H*6){started=false;continue}if(!started){ctx.moveTo(px,py);started=true}else ctx.lineTo(px,py)}ctx.stroke()});$('graphStatus').textContent=errors.length?'函數格式有誤：'+errors[0]:`已繪製 ${expressions.filter(Boolean).length} 條函數`; }
$('graphDraw').addEventListener('click',drawGraph);$('graphDraw2').addEventListener('click',drawGraph);$('graphReset').addEventListener('click',()=>{$('xMin').value=-5;$('xMax').value=5;$('yMin').value=-8;$('yMax').value=8;drawGraph()});
$$('[data-fn]').forEach(b=>b.addEventListener('click',()=>{$('functionA').value=b.dataset.fn;drawGraph()}));
let graphDrag=null;$('graphCanvas').addEventListener('pointerdown',e=>{graphDrag={x:e.clientX,y:e.clientY,xmin:Number($('xMin').value),xmax:Number($('xMax').value),ymin:Number($('yMin').value),ymax:Number($('yMax').value)};$('graphCanvas').setPointerCapture(e.pointerId)});$('graphCanvas').addEventListener('pointermove',e=>{if(!graphDrag||!(e.buttons&1))return;const r=$('graphCanvas').getBoundingClientRect(),dx=(e.clientX-graphDrag.x)/r.width*(graphDrag.xmax-graphDrag.xmin),dy=(e.clientY-graphDrag.y)/r.height*(graphDrag.ymax-graphDrag.y);$('xMin').value=fmt(graphDrag.xmin-dx);$('xMax').value=fmt(graphDrag.xmax-dx);$('yMin').value=fmt(graphDrag.ymin+dy);$('yMax').value=fmt(graphDrag.ymax+dy);drawGraph()});$('graphCanvas').addEventListener('pointerup',()=>graphDrag=null);$('graphCanvas').addEventListener('wheel',e=>{e.preventDefault();const factor=e.deltaY>0?1.12:.89;const midx=(Number($('xMin').value)+Number($('xMax').value))/2,midy=(Number($('yMin').value)+Number($('yMax').value))/2;const xr=(Number($('xMax').value)-Number($('xMin').value))*factor,yr=(Number($('yMax').value)-Number($('yMin').value))*factor;$('xMin').value=fmt(midx-xr/2);$('xMax').value=fmt(midx+xr/2);$('yMin').value=fmt(midy-yr/2);$('yMax').value=fmt(midy+yr/2);drawGraph()},{passive:false});window.addEventListener('resize',()=>{if($('page-graph').classList.contains('active'))drawGraph()});
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>{const tab=b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));['Linear','Quadratic','System'].forEach(s=>$('solver'+s).classList.toggle('hidden',s.toLowerCase()!==tab))}));
$('solveLinear').addEventListener('click',()=>{try{const a=num('linA'),b=num('linB');let html;if(a===0)html=b===0?'無限多組解。':'無解。';else{const x=-b/a;html=`<strong>答案</strong><span class="answer">x = ${fmt(x)}</span><div class="step">ax + b = 0</div><div class="step">${fmt(a)}x = ${fmt(-b)}</div><div class="step">x = −b ÷ a = ${fmt(x)}</div>`;saveHistory('一次方程式',`${a}x + (${b}) = 0`,`x = ${fmt(x)}`)}$('linearResult').innerHTML=html}catch(e){toast(e.message)}});
$('solveQuadratic').addEventListener('click',()=>{try{const a=num('quadA'),b=num('quadB'),c=num('quadC');let html;if(a===0){if(b===0)html=c===0?'所有 x 都成立。':'無解。';else html=`<strong>退化為一次方程式</strong><span class="answer">x = ${fmt(-c/b)}</span>`}else{const d=b*b-4*a*c;if(d>0){const x1=(-b+Math.sqrt(d))/(2*a),x2=(-b-Math.sqrt(d))/(2*a);html=`<strong>判別式 Δ = b² − 4ac</strong><span class="answer">Δ = ${fmt(d)}</span><div class="step">因為 Δ &gt; 0，有兩個相異實根。</div><span class="answer">x₁ = ${fmt(x1)}</span><span class="answer">x₂ = ${fmt(x2)}</span>`}else if(d===0){html=`<strong>判別式 Δ = 0</strong><span class="answer">x = ${fmt(-b/(2*a))}</span><div class="step">有兩個相同的實根。</div>`}else{const re=-b/(2*a),im=Math.sqrt(-d)/(2*a);html=`<strong>判別式 Δ = ${fmt(d)} &lt; 0</strong><span class="answer">x = ${fmt(re)} ± ${fmt(Math.abs(im))}i</span><div class="step">沒有實數根；以上為複數根。</div>`}}$('quadraticResult').innerHTML=html;saveHistory('二次方程式',`${a}x² + (${b})x + (${c}) = 0`,html.replace(/<[^>]*>/g,' '))}catch(e){toast(e.message)}});
$('solveSystem').addEventListener('click',()=>{try{const a=num('sysA1'),b=num('sysB1'),c=num('sysC1'),d=num('sysA2'),e=num('sysB2'),f=num('sysC2'),det=a*e-b*d;if(Math.abs(det)<1e-12){$('systemResult').textContent=Math.abs(a*f-c*d)<1e-12&&Math.abs(b*f-c*e)<1e-12?'兩式可能相依，有無限多組解。':'兩式平行或矛盾，沒有唯一解。';return}const x=(c*e-b*f)/det,y=(a*f-c*d)/det;$('systemResult').innerHTML=`<strong>克拉瑪公式</strong><div class="step">D = a₁b₂ − a₂b₁ = ${fmt(det)}</div><span class="answer">x = ${fmt(x)}</span><span class="answer">y = ${fmt(y)}</span>`;saveHistory('二元聯立方程式',`${a}x+${b}y=${c}; ${d}x+${e}y=${f}`,`x=${fmt(x)}, y=${fmt(y)}`)}catch(e){toast(e.message)}});
$$('[data-seq]').forEach(b=>b.addEventListener('click',()=>{currentSequence=b.dataset.seq;$$('[data-seq]').forEach(x=>x.classList.toggle('active',x===b));$('seqArithmetic').classList.toggle('hidden',currentSequence!=='arithmetic');$('seqGeometric').classList.toggle('hidden',currentSequence!=='geometric')}));
$('solveSequence').addEventListener('click',()=>{try{let a1,d,n,an,sum,terms;if(currentSequence==='arithmetic'){a1=num('seqA1');d=num('seqD');n=Math.floor(num('seqN'));if(n<1||n>1000)throw new Error('項數需介於 1 到 1000。');an=a1+(n-1)*d;sum=n*(a1+an)/2;terms=Array.from({length:Math.min(n,30)},(_,i)=>fmt(a1+i*d));}else{a1=num('geoA1');d=num('geoR');n=Math.floor(num('geoN'));if(n<1||n>1000)throw new Error('項數需介於 1 到 1000。');an=a1*Math.pow(d,n-1);sum=d===1?a1*n:a1*(1-Math.pow(d,n))/(1-d);terms=Array.from({length:Math.min(n,30)},(_,i)=>fmt(a1*Math.pow(d,i)));}const title=currentSequence==='arithmetic'?'等差數列':'等比數列';$('sequenceResult').innerHTML=`<strong>${title}結果</strong><span class="answer">第 ${n} 項 = ${fmt(an)}</span><span class="answer">前 ${n} 項和 = ${fmt(sum)}</span><div class="step">前 ${Math.min(n,30)} 項：${terms.join('、')}${n>30?' …':''}</div>`;saveHistory(title,`a₁=${a1}, ${currentSequence==='arithmetic'?'d':'r'}=${d}, n=${n}`,`aₙ=${fmt(an)}, Sₙ=${fmt(sum)}`)}catch(e){toast(e.message)}});
$$('[data-geo]').forEach(b=>b.addEventListener('click',()=>{currentGeometry=b.dataset.geo;$$('[data-geo]').forEach(x=>x.classList.toggle('active',x===b));['Distance','Slope','Circle','Triangle','RightTriangle','Rectangle'].forEach(s=>$('geo'+s).classList.toggle('hidden',s.toLowerCase()!==currentGeometry))}));
$('solveGeometry').addEventListener('click',()=>{try{let html,expr;if(currentGeometry==='distance'){const x1=num('distX1'),y1=num('distY1'),x2=num('distX2'),y2=num('distY2'),d=Math.hypot(x2-x1,y2-y1);expr=`(${x1},${y1}) 到 (${x2},${y2})`;html=`<strong>兩點距離公式</strong><span class="answer">d = ${fmt(d)}</span><div class="step">d = √[(${fmt(x2)}−${fmt(x1)})² + (${fmt(y2)}−${fmt(y1)})²]</div>`}else if(currentGeometry==='slope'){const x1=num('slopeX1'),y1=num('slopeY1'),x2=num('slopeX2'),y2=num('slopeY2');expr='兩點斜率';html=x1===x2?'<strong>垂直直線</strong><span class="answer">斜率不存在</span>':`<strong>斜率公式</strong><span class="answer">m = ${fmt((y2-y1)/(x2-x1))}</span><div class="step">m = (${y2}−${y1}) ÷ (${x2}−${x1})</div>`}else if(currentGeometry==='circle'){const r=num('circleR');if(r<0)throw new Error('半徑不可為負數。');expr=`圓半徑 ${r}`;html=`<strong>圓形計算</strong><span class="answer">周長 = ${fmt(2*Math.PI*r)}</span><span class="answer">面積 = ${fmt(Math.PI*r*r)}</span>`}else if(currentGeometry==='triangle'){const b=num('triBase'),h=num('triHeight');if(b<0||h<0)throw new Error('底與高不可為負數。');expr=`三角形底 ${b} 高 ${h}`;html=`<strong>三角形面積</strong><span class="answer">A = ${fmt(b*h/2)}</span><div class="step">A = ${b} × ${h} ÷ 2</div>`}else if(currentGeometry==='righttriangle'){const a=num('rightA'),b=num('rightB');if(a<=0||b<=0)throw new Error('直角邊長必須大於 0。');const c=Math.hypot(a,b);expr=`直角三角形兩股 ${a}, ${b}`;html=`<strong>直角三角形結果</strong><span class="answer">斜邊 c = ${fmt(c)}</span><span class="answer">面積 = ${fmt(a*b/2)}</span><div class="step">c = √(${a}² + ${b}²) = ${fmt(c)}</div>`}else{const l=num('rectL'),w=num('rectW');if(l<0||w<0)throw new Error('長與寬不可為負數。');expr=`長方形 ${l} × ${w}`;html=`<strong>長方形計算</strong><span class="answer">周長 = ${fmt(2*(l+w))}</span><span class="answer">面積 = ${fmt(l*w)}</span>`} $('geometryResult').innerHTML=html;saveHistory('幾何計算',expr,html.replace(/<[^>]*>/g,' '))}catch(e){toast(e.message)}});
function parseFormula(formula){let s=formula.replace(/\s+/g,'');let i=0;function group(){const counts={};while(i<s.length&&s[i]!==')'){if(s[i]==='('){i++;const inner=group();if(s[i]!==')')throw new Error('括號不成對：'+formula);i++;let digits='';while(/\d/.test(s[i]||'')){digits+=s[i++]}const mult=digits?Number(digits):1;Object.entries(inner).forEach(([el,n])=>counts[el]=(counts[el]||0)+n*mult)}else if(/[A-Z]/.test(s[i])){let el=s[i++];while(/[a-z]/.test(s[i]||''))el+=s[i++];let digits='';while(/\d/.test(s[i]||''))digits+=s[i++];counts[el]=(counts[el]||0)+(digits?Number(digits):1)}else throw new Error('無法解析化學式：'+formula)}return counts}const out=group();if(i!==s.length)throw new Error('化學式格式錯誤：'+formula);return out}
function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){const t=a%b;a=b;b=t}return a||1}
function lcm(a,b){return Math.abs(a*b)/gcd(a,b)}
function rational(x){if(!Number.isFinite(x))throw new Error('無法求解此反應式。');if(Math.abs(x)<1e-10)return [0,1];let best=[Math.round(x),1],err=Math.abs(x-best[0]);for(let d=1;d<=1000;d++){const n=Math.round(x*d),e=Math.abs(x-n/d);if(e<err){best=[n,d];err=e}if(err<1e-10)break}return best}
function nullVector(matrix){const A=matrix.map(row=>row.map(v=>rational(v)));let rows=A.length,cols=A[0].length; // Use floating Gaussian elimination for small stoichiometry matrices.
 const M=matrix.map(r=>r.slice()),pivots=[];let r=0;for(let c=0;c<cols&&r<rows;c++){let best=r;for(let rr=r+1;rr<rows;rr++)if(Math.abs(M[rr][c])>Math.abs(M[best][c]))best=rr;if(Math.abs(M[best][c])<1e-10)continue;[M[r],M[best]]=[M[best],M[r]];const v=M[r][c];for(let j=c;j<cols;j++)M[r][j]/=v;for(let rr=0;rr<rows;rr++){if(rr===r)continue;const factor=M[rr][c];for(let j=c;j<cols;j++)M[rr][j]-=factor*M[r][j]}pivots.push(c);r++}const free=[];for(let c=0;c<cols;c++)if(!pivots.includes(c))free.push(c);if(free.length!==1)throw new Error(free.length===0?'此反應式沒有非零解，請檢查化學式。':'此反應式有多組自由係數，暫時無法自動判定唯一的最簡配平。');const v=Array(cols).fill(0);v[free[0]]=1;pivots.forEach((c,rr)=>v[c]=-M[rr][free[0]]);if(v.some(x=>x<-1e-8))throw new Error('求得的係數不是全正值；請檢查反應物與生成物。');let den=1;v.forEach(x=>{den=lcm(den,rational(x)[1]);if(den>1e8)throw new Error('係數過於複雜，請確認輸入。')});let ints=v.map(x=>Math.round(x*den));let g=ints.reduce((a,b)=>gcd(a,b),0);ints=ints.map(x=>x/g);if(ints.some(x=>x<=0))throw new Error('無法得到全正整數係數。');return ints}
function balanceChemical(raw){const sides=raw.replace(/→|⟶|=/g,'->').split(/->|→/);if(sides.length!==2)throw new Error('請用 → 或 -> 分隔反應物與生成物。');const left=sides[0].split('+').map(s=>s.trim()).filter(Boolean),right=sides[1].split('+').map(s=>s.trim()).filter(Boolean);if(left.length<1||right.length<1)throw new Error('反應式左右兩側都需要有物質。');const all=[...left,...right];if(all.length>12)throw new Error('一次最多處理 12 種物質。');const formulas=all.map(parseFormula),elements=[...new Set(formulas.flatMap(f=>Object.keys(f)))];const matrix=elements.map(el=>formulas.map((f,i)=>(i<left.length?1:-1)*(f[el]||0)));const coeffs=nullVector(matrix);const format=(formula,c)=>`${c===1?'':c}${formula}`;const balanced=left.map((f,i)=>format(f,coeffs[i])).join(' + ')+' → '+right.map((f,i)=>format(f,coeffs[left.length+i])).join(' + ');const rows=elements.map(el=>{let l=0,r=0;formulas.forEach((f,i)=>{if(i<left.length)l+=(f[el]||0)*coeffs[i];else r+=(f[el]||0)*coeffs[i]});return {el,l,r,ok:l===r}});return {balanced,rows,coeffs,left,right,formulas}}
$('balanceEquation').addEventListener('click',()=>{try{const result=balanceChemical($('chemicalEquation').value);$('chemResult').innerHTML=`<strong>最簡整數配平結果</strong><span class="answer">${result.balanced}</span><div class="step">係數：${result.coeffs.join(' : ')}</div><div class="step">已確認左右兩側各元素原子數相同。</div>`;$('atomCheck').innerHTML=result.rows.map(r=>`<div class="atom-row"><span>${r.el}</span><b>${r.l} ${r.ok?'＝':'≠'} ${r.r}</b></div>`).join('');saveHistory('化學配平',$('chemicalEquation').value,result.balanced)}catch(e){$('chemResult').innerHTML=`<strong>無法配平</strong><div class="step">${e.message}</div>`;$('atomCheck').innerHTML='<span class="muted">請先修正輸入格式，再重新配平。</span>';toast(e.message)}});
$$('[data-chem]').forEach(b=>b.addEventListener('click',()=>{$('chemicalEquation').value=b.dataset.chem;$('balanceEquation').click()}));
const physicsData=[
{title:'速度與時間',formula:'v = v₀ + at',desc:'已知初速度、加速度與時間，求末速度。',vars:['v0','a','t','v'],labels:{v0:'初速度 v₀（m/s）',a:'加速度 a（m/s²）',t:'時間 t（s）',v:'末速度 v（m/s）'},solve:(u,x)=>{if(x==='v')return u.v0+u.a*u.t;if(x==='v0')return u.v-u.a*u.t;if(x==='a'){if(u.t===0)throw Error('時間為 0，無法求加速度。');return (u.v-u.v0)/u.t}if(x==='t'){if(u.a===0)throw Error('加速度為 0 時，無法由此式唯一求時間。');return (u.v-u.v0)/u.a}},
},
{title:'位移與時間',formula:'s = v₀t + ½at²',desc:'已知初速度、加速度與時間，求位移；也可由其他三項反求未知量。',vars:['v0','a','t','s'],labels:{v0:'初速度 v₀（m/s）',a:'加速度 a（m/s²）',t:'時間 t（s）',s:'位移 s（m）'},solve:(u,x)=>{if(x==='s')return u.v0*u.t+.5*u.a*u.t*u.t;if(x==='v0'){if(u.t===0)throw Error('時間為 0，無法反求初速度。');return (u.s-.5*u.a*u.t*u.t)/u.t}if(x==='a'){if(u.t===0)throw Error('時間為 0，無法反求加速度。');return 2*(u.s-u.v0*u.t)/(u.t*u.t)}if(x==='t'){const A=.5*u.a,B=u.v0,C=-u.s;if(Math.abs(A)<1e-12){if(B===0)throw Error('此條件無法求時間。');return -C/B}const d=B*B-4*A*C;if(d<0)throw Error('沒有實數時間解。');const ts=[(-B+Math.sqrt(d))/(2*A),(-B-Math.sqrt(d))/(2*A)].filter(t=>t>=0);if(!ts.length)throw Error('沒有非負時間解。');return Math.min(...ts)}}
},
{title:'速度與位移',formula:'v² = v₀² + 2as',desc:'不含時間的等加速度公式，適合已知位移與速度的情況。',vars:['v0','a','s','v'],labels:{v0:'初速度 v₀（m/s）',a:'加速度 a（m/s²）',s:'位移 s（m）',v:'末速度 v（m/s）'},solve:(u,x)=>{if(x==='v'){const q=u.v0*u.v0+2*u.a*u.s;if(q<0)throw Error('根號內小於 0，沒有實數速度。');return Math.sqrt(q)}if(x==='v0'){const q=u.v*u.v-2*u.a*u.s;if(q<0)throw Error('根號內小於 0，沒有實數初速度大小。');return Math.sqrt(q)}if(x==='a'){if(u.s===0)throw Error('位移為 0，無法由此式唯一求加速度。');return (u.v*u.v-u.v0*u.v0)/(2*u.s)}if(x==='s'){if(u.a===0)throw Error('加速度為 0，無法由此式唯一求位移。');return (u.v*u.v-u.v0*u.v0)/(2*u.a)}}
},
{title:'平均速度',formula:'s = ½(v₀ + v)t',desc:'等加速度運動的平均速度為初、末速度的平均值。',vars:['v0','v','t','s'],labels:{v0:'初速度 v₀（m/s）',v:'末速度 v（m/s）',t:'時間 t（s）',s:'位移 s（m）'},solve:(u,x)=>{if(x==='s')return .5*(u.v0+u.v)*u.t;if(x==='v0'){if(u.t===0)throw Error('時間為 0，無法反求初速度。');return 2*u.s/u.t-u.v}if(x==='v'){if(u.t===0)throw Error('時間為 0，無法反求末速度。');return 2*u.s/u.t-u.v0}if(x==='t'){if(u.v0+u.v===0)throw Error('初、末速度總和為 0，無法反求時間。');return 2*u.s/(u.v0+u.v)}}
}
];
function renderPhysics(){const d=physicsData[currentPhysics];$$('[data-physics]').forEach(b=>b.classList.toggle('active',Number(b.dataset.physics)===currentPhysics));$('physicsFormulaTag').textContent='FORMULA 0'+(currentPhysics+1);$('physicsFormulaTitle').textContent=d.title;$('physicsFormulaDisplay').textContent=d.formula;$('physicsFormulaDesc').textContent=d.desc;$('physicsInputs').innerHTML=d.vars.map(v=>`<label>${d.labels[v]}<input type="number" step="any" data-pvar="${v}" placeholder="輸入數值"></label>`).join('');$('physicsUnknown').innerHTML=d.vars.map(v=>`<option value="${v}">${d.labels[v].split('（')[0]}</option>`).join('');const preferred=d.vars[d.vars.length-1];$('physicsUnknown').value=preferred;$('physicsResult').textContent='填入除未知量以外的已知數值，再按計算。'}
$$('[data-physics]').forEach(b=>b.addEventListener('click',()=>{currentPhysics=Number(b.dataset.physics);renderPhysics()}));
$('solvePhysics').addEventListener('click',()=>{try{const d=physicsData[currentPhysics],unknown=$('physicsUnknown').value,u={};for(const v of d.vars){if(v===unknown)continue;const input=document.querySelector(`[data-pvar="${v}"]`);if(!input||input.value.trim()==='')throw new Error('請填入已知量，未知量留空即可。');u[v]=Number(input.value);if(!Number.isFinite(u[v]))throw new Error('請輸入有效數值。')}const ans=d.solve(u,unknown);if(!Number.isFinite(ans))throw new Error('無法得到有限解。');$('physicsResult').innerHTML=`<strong>計算結果</strong><span class="answer">${d.labels[unknown].split('（')[0]} = ${fmt(ans)}</span><div class="step">使用公式：${d.formula}</div><div class="step">將已知數值代入並整理，得到 ${fmt(ans)}。</div><div class="step">請依題目要求確認方向、正負號與單位。</div>`;saveHistory('物理運動公式',d.formula+'；求 '+unknown,fmt(ans))}catch(e){$('physicsResult').textContent=e.message;toast(e.message)}});
