function renderPeriodic(){const grid=$('periodicGrid');if(!grid)return;const q=$('elementSearch').value.trim().toLowerCase();grid.innerHTML='';for(let row=1;row<=9;row++){for(let col=1;col<=18;col++){if((row===8||row===9)&&col===1){const p=document.createElement('div');p.className='element-placeholder';p.style.gridColumn='1';p.style.gridRow=String(row);p.textContent=row===8?'鑭系':'錒系';grid.appendChild(p);continue}let el=elementRows.find(e=>e[5]===col&&e[6]===row);if(row===6&&col===3)el=null;if(row===7&&col===3)el=null;if(el){const match=!q||String(el[0]).includes(q)||el[1].toLowerCase().includes(q)||el[2].toLowerCase().includes(q);const b=document.createElement('button');b.className='element '+el[4];b.style.gridColumn=String(col);b.style.gridRow=String(row);b.dataset.z=el[0];b.title=`${el[2]} ${el[1]} · ${el[0]}`;b.innerHTML=`<span class="anum">${el[0]}</span><span class="sym">${el[1]}</span><span class="ename">${el[2]}</span>`;if(!match)b.style.opacity='.16';b.addEventListener('click',()=>showElement(el));grid.appendChild(b)}else if((row===6||row===7)&&col===3){const p=document.createElement('div');p.className='element-placeholder';p.style.gridColumn=String(col);p.style.gridRow=String(row);p.textContent=row===6?'57–71':'89–103';grid.appendChild(p)}}}const selected=elementRows.find(e=>e[1]===$('elementDetail').dataset.symbol)||elementRows[0];if(!selected)showElement(elementRows[0])}
function showElement(el){$('elementDetail').dataset.symbol=el[1];$('elementDetail').innerHTML=`<div class="element-big" style="background:${el[4]==='metal'?'#e8ebff':el[4]==='noble'?'#fff0df':el[4]==='metalloid'?'#fff7cf':'#dff8ed'};color:${el[4]==='metal'?'#4e5cb4':el[4]==='noble'?'#a85c1c':el[4]==='metalloid'?'#886c08':'#167a5b'}">${el[1]}</div><div><span class="eyebrow">ELEMENT DETAILS</span><h3>${el[2]} ${el[1]}</h3><p>原子序 ${el[0]} · 相對原子量 ${el[3]}</p></div><span class="pill pill-cyan">${({metal:'金屬',nonmetal:'非金屬',noble:'惰性氣體',metalloid:'類金屬',other:'其他'})[el[4]]||'元素'}</span>`;$$('.element').forEach(b=>b.classList.toggle('selected',Number(b.dataset.z)===el[0]))}
$('elementSearch').addEventListener('input',renderPeriodic);
const lessonData=[
{id:'linear',title:'一次方程式',subject:'math',level:'middle',icon:'＝',color:'#ece9ff',description:'理解等式的平衡與移項，求出未知數。',concept:'方程式是一個含有未知數的等式。解方程式的目標是找出讓等式成立的未知數值。等式兩邊同時加、減、乘或除以同一個非零數，等式仍然成立。',formula:'ax + b = 0，且 a ≠ 0 時，x = −b/a。',example:'解 3x + 6 = 15。先兩邊同減 6，得到 3x = 9；再兩邊同除以 3，得到 x = 3。代回原式：3×3+6=15，成立。',tool:'equations',quiz:{q:'方程式 2x + 4 = 10 的解為何？',options:['x = 2','x = 3','x = 7'],answer:1,explain:'兩邊同減 4 得 2x=6，再同除以 2，所以 x=3。'}},
{id:'quadratic',title:'二次方程式',subject:'math',level:'high',icon:'x²',color:'#ece9ff',description:'使用判別式與公式求根。',concept:'標準形式為 ax²+bx+c=0，其中 a 不等於 0。判別式 Δ=b²−4ac 可以判斷實根的數量。',formula:'x = (−b ± √(b²−4ac)) / (2a)。',example:'解 x²−5x+6=0。a=1、b=−5、c=6，因此 Δ=25−24=1。根為 (5±1)/2，得到 x=3 或 x=2。',tool:'equations',quiz:{q:'若判別式 Δ < 0，方程式有幾個實數根？',options:['兩個相異實根','一個重根','沒有實數根'],answer:2,explain:'判別式小於零時，根號內為負數，因此沒有實數根。'}},
{id:'cubic',title:'三次函數圖形',subject:'math',level:'high',icon:'x³',color:'#e8e6ff',description:'觀察三次函數的曲線、係數與轉折。',concept:'三次函數常見形式為 y=ax³+bx²+cx+d，且 a 不等於 0。當 x 趨向正負無限大時，端點方向主要由最高次項 ax³ 的係數決定。不同係數會改變曲線的伸展、平移與彎曲方式。',formula:'y = ax³ + bx² + cx + d。',example:'觀察 y=x³−3x。改變 x 的值，函數值會跟著變化；將它和 y=x² 放在同一座標平面比較，可以看出三次與二次函數的形狀差異。',tool:'graph',quiz:{q:'函數 y=2x³ 的最高次項係數為何？',options:['0','2','3'],answer:1,explain:'最高次項是 2x³，所以係數為 2。'}},
{id:'sequence',title:'等差數列',subject:'math',level:'middle',icon:'Σ',color:'#e1f8ef',description:'求公差、通項公式與前 n 項和。',concept:'等差數列相鄰兩項的差固定，這個固定的差叫作公差 d。知道首項、公差和項數，就能求出任意一項。',formula:'aₙ=a₁+(n−1)d；Sₙ=n(a₁+aₙ)/2。',example:'數列 3、5、7、9、… 的首項是 3、公差是 2。第 8 項為 3+(8−1)×2=17；前 8 項和為 8×(3+17)/2=80。',tool:'sequences',quiz:{q:'數列 4、7、10、13、… 的公差是多少？',options:['2','3','4'],answer:1,explain:'相鄰兩項相減：7−4=3，因此公差是 3。'}},
{id:'geometry',title:'座標與兩點距離',subject:'math',level:'middle',icon:'△',color:'#e7f0ff',description:'計算平面座標兩點之間的距離。',concept:'平面上兩點 A(x₁,y₁)、B(x₂,y₂) 的水平差為 x₂−x₁，垂直差為 y₂−y₁。由畢氏定理可得兩點間的直線距離。',formula:'d=√[(x₂−x₁)²+(y₂−y₁)²]。',example:'A(1,2)、B(4,6)，水平差為 3，垂直差為 4。距離 d=√(3²+4²)=√25=5。',tool:'geometry',quiz:{q:'兩點的水平差是 3、垂直差是 4，距離為何？',options:['5','7','12'],answer:0,explain:'距離為 √(3²+4²)=√25=5。'}},
{id:'chem-balance',title:'化學方程式配平',subject:'chemistry',level:'middle',icon:'⚗',color:'#fff0e4',description:'利用原子守恆調整反應式係數。',concept:'化學反應前後，原子的種類與數量守恆。配平時只能調整化學式前面的係數，不能任意更改化學式內的下標。最後要化成最簡整數比。',formula:'反應物各元素原子總數 = 生成物各元素原子總數。',example:'H₂+O₂→H₂O。右側有 2 個氫、1 個氧；先將水前係數改為 2，右側有 4 個氫與 2 個氧，再將氫氣前係數改為 2，得到 2H₂+O₂→2H₂O。',tool:'chemistry',quiz:{q:'配平化學方程式時，應調整哪裡？',options:['化學式下標','物質前面的係數','元素符號'],answer:1,explain:'調整反應物或生成物前的係數，才能保留物質本身的化學式。'}},
{id:'motion',title:'等加速度運動',subject:'physics',level:'high',icon:'↗',color:'#e1f8fa',description:'理解初速度、末速度、加速度、時間與位移。',concept:'當物體沿直線運動且加速度固定時，可以使用等加速度運動公式。先整理題目已知與未知量，再挑選包含所求量的公式。',formula:'v=v₀+at；s=v₀t+½at²；v²=v₀²+2as；s=½(v₀+v)t。',example:'物體初速度為 2 m/s，加速度為 3 m/s²，經過 4 秒。由 v=v₀+at 得 v=2+3×4=14 m/s。',tool:'physics',quiz:{q:'初速度 2 m/s、加速度 3 m/s²、時間 4 s，末速度是多少？',options:['9 m/s','12 m/s','14 m/s'],answer:2,explain:'v=v₀+at=2+3×4=14 m/s。'}},
{id:'trig',title:'三角函數入門',subject:'math',level:'high',icon:'∠',color:'#ffebf3',description:'認識 sin、cos、tan 與角度模式。',concept:'在直角三角形中，對角 θ 而言，sinθ=對邊/斜邊，cosθ=鄰邊/斜邊，tanθ=對邊/鄰邊。角度制與弧度制是兩種不同的角度表示方式。',formula:'sin²θ+cos²θ=1。',example:'在角度制下，sin 30°=1/2。計算機若設定成弧度制，輸入 30 代表 30 弧度而不是 30°，結果會不同。',tool:'calculator',quiz:{q:'直角三角形中，sinθ 等於什麼？',options:['鄰邊／斜邊','對邊／斜邊','對邊／鄰邊'],answer:1,explain:'正弦值是對邊長度除以斜邊長度。'}},
{id:'unit',title:'物理單位與換算',subject:'physics',level:'middle',icon:'⇄',color:'#e7f0ff',description:'理解常見 SI 單位與單位換算。',concept:'物理量通常需要數值與單位一起表示。進行運算前，最好先統一單位，避免把公里與公尺、分鐘與秒直接混用。',formula:'1 km=1000 m；1 h=3600 s；1 m/s=3.6 km/h。',example:'72 km/h 換算成 m/s：72÷3.6=20 m/s。',tool:'converter',quiz:{q:'36 km/h 等於多少 m/s？',options:['10 m/s','12.96 m/s','36 m/s'],answer:0,explain:'公里/小時換算公尺/秒要除以 3.6，因此 36÷3.6=10。'}},
{id:'linear-function',title:'一次函數圖形',subject:'math',level:'middle',icon:'↗',color:'#e7f0ff',description:'認識 y=ax+b 的斜率與截距。',concept:'一次函數 y=ax+b 的圖形是一條直線。a 是斜率，描述 x 增加時 y 的變化率；b 是 y 截距，也就是 x=0 時的函數值。',formula:'y=ax+b。',example:'y=2x+1 的斜率是 2，y 截距是 1。當 x=2 時，y=2×2+1=5。',tool:'graph',quiz:{q:'y=−3x+2 的斜率是多少？',options:['2','−3','3'],answer:1,explain:'一次函數 y=ax+b 的斜率就是 x 的係數 a。'}},
{id:'quadratic-function',title:'二次函數圖形',subject:'math',level:'high',icon:'⌒',color:'#ece9ff',description:'觀察拋物線開口與頂點。',concept:'二次函數 y=ax²+bx+c 的圖形是拋物線。a>0 時開口向上，a<0 時開口向下。頂點的 x 座標為 −b/(2a)。',formula:'y=ax²+bx+c；頂點 x=−b/(2a)。',example:'y=x²−4x+3 中，a=1、b=−4，所以頂點 x=2；代回 y=4−8+3=−1，頂點為 (2,−1)。',tool:'graph',quiz:{q:'若二次函數的 a<0，拋物線開口方向為何？',options:['向上','向下','水平'],answer:1,explain:'a<0 時，x² 項係數為負，拋物線開口向下。'}},
{id:'newton',title:'牛頓第二運動定律',subject:'physics',level:'high',icon:'⚙',color:'#e1f8fa',description:'理解合力、質量與加速度的關係。',concept:'物體所受合力會造成加速度。合力越大，在質量不變時加速度越大；質量越大，在合力相同時加速度越小。',formula:'F=ma。',example:'質量 2 kg 的物體受到 10 N 合力，則加速度 a=F/m=10/2=5 m/s²。',tool:'physics',quiz:{q:'2 kg 的物體受到 10 N 合力，加速度是多少？',options:['5 m/s²','20 m/s²','12 m/s²'],answer:0,explain:'由 F=ma，a=F/m=10/2=5 m/s²。'}},
{"id":"math-elective-vectors","title":"選修數學：空間向量","subject":"math","level":"elective","icon":"↗","color":"#e7e6ff","description":"空間向量、內積與幾何關係。","concept":"三維向量可用 (x,y,z) 表示。向量內積 a·b = |a||b|cosθ，也等於對應分量乘積的總和。內積可用來求夾角、判斷垂直與計算投影。","formula":"a·b = a₁b₁ + a₂b₂ + a₃b₃。","example":"a=(1,2,2)、b=(2,0,1)，內積為 1×2+2×0+2×1=4。","tool":"calculator","quiz":{"q":"若兩個非零向量內積為 0，代表什麼？","options":["兩向量垂直","兩向量平行","兩向量長度相同"],"answer":0,"explain":"內積為 |a||b|cosθ；非零向量內積為 0，表示 cosθ=0，因此夾角為 90°。"}},
{"id":"math-elective-probability","title":"選修數學：條件機率","subject":"math","level":"elective","icon":"P(A)","color":"#e7e6ff","description":"理解條件機率與獨立事件。","concept":"在已知事件 B 發生的條件下，事件 A 發生的機率為 P(A|B)=P(A∩B)/P(B)，前提是 P(B)>0。若 A、B 獨立，則 P(A∩B)=P(A)P(B)。","formula":"P(A|B)=P(A∩B)/P(B)。","example":"袋中有 3 顆紅球、2 顆藍球，不放回抽球。已知第一顆是紅球，剩下 4 顆中有 2 顆紅球，所以第二顆紅球的條件機率是 2/4=1/2。","tool":"calculator","quiz":{"q":"若 P(A∩B)=0.2、P(B)=0.5，P(A|B) 為何？","options":["0.1","0.4","0.7"],"answer":1,"explain":"P(A|B)=0.2/0.5=0.4。"}},
{"id":"math-elective-matrix","title":"選修數學：矩陣運算","subject":"math","level":"elective","icon":"▦","color":"#e7e6ff","description":"矩陣加法、乘法與線性方程組。","concept":"矩陣加法需同型矩陣；矩陣乘法 A(m×n)B(n×p) 才能進行，結果為 m×p。一般而言 AB 不一定等於 BA。","formula":"(AB)ᵢⱼ = Σₖ aᵢₖbₖⱼ。","example":"A=[[1,2],[0,1]]、B=[[2,0],[1,3]]，AB=[[4,6],[1,3]]。","tool":"calculator","quiz":{"q":"A 為 2×3 矩陣，B 為 3×4 矩陣，AB 的型態為何？","options":["2×4","3×3","4×2"],"answer":0,"explain":"內側維度 3 相同可相乘，結果型態取外側維度 2×4。"}},
{"id":"physics-elective-electric","title":"選修物理：電場與電位","subject":"physics","level":"elective","icon":"⚡","color":"#dff8fa","description":"電場、電位差與電力方向。","concept":"電場定義為單位正試驗電荷所受電力 E=F/q。電位差描述單位電荷的電位能變化；電場方向定義為正電荷受力方向。","formula":"E=F/q；均勻電場中 |ΔV|=Ed（沿電場方向）。","example":"若 2 C 電荷在某處受到 6 N 電力，該處電場大小 E=6/2=3 N/C。","tool":"physics","quiz":{"q":"正電荷放入電場，受力方向如何？","options":["與電場方向相同","與電場方向相反","一定垂直電場"],"answer":0,"explain":"電場方向定義為正試驗電荷受力方向。"}},
{"id":"physics-elective-circuit","title":"選修物理：電路與電容","subject":"physics","level":"elective","icon":"🔋","color":"#dff8fa","description":"歐姆定律、電功率與電容。","concept":"電阻元件遵守 V=IR。電功率可寫成 P=VI，也可利用 V=IR 推得 P=I²R 或 P=V²/R。電容器儲存電荷，C=Q/V。","formula":"V=IR；P=VI；C=Q/V。","example":"電阻為 4 Ω、電流為 2 A，電壓 V=IR=8 V，功率 P=VI=16 W。","tool":"physics","quiz":{"q":"4 Ω 電阻通過 2 A 電流，功率為何？","options":["8 W","16 W","32 W"],"answer":1,"explain":"P=I²R=2²×4=16 W。"}},
{"id":"physics-elective-wave","title":"選修物理：波動與干涉","subject":"physics","level":"elective","icon":"〰","color":"#dff8fa","description":"波速、頻率、波長與干涉條件。","concept":"波速 v=fλ，其中 f 為頻率、λ 為波長。同一介質中的波速若固定，頻率增加時波長會減小。相干波疊加可能形成建設性或破壞性干涉。","formula":"v=fλ。","example":"波速為 12 m/s、頻率為 3 Hz，波長 λ=v/f=4 m。","tool":"physics","quiz":{"q":"波速 20 m/s、波長 5 m，頻率是多少？","options":["4 Hz","25 Hz","100 Hz"],"answer":0,"explain":"f=v/λ=20/5=4 Hz。"}},
{"id":"chem-elective-equilibrium","title":"選修化學：化學平衡","subject":"chemistry","level":"elective","icon":"⇌","color":"#fff0e4","description":"平衡常數與勒沙特列原理。","concept":"可逆反應達到動態平衡時，正逆反應速率相等，各物質濃度在固定條件下維持不變。改變濃度、壓力或溫度可能使平衡移動；催化劑只加快到達平衡，不改變平衡常數。","formula":"aA+bB ⇌ cC+dD，Kc=[C]^c[D]^d/([A]^a[B]^b)。","example":"增加反應物濃度時，系統通常會往消耗新增反應物的方向移動，以重新建立平衡。","tool":"chemistry","quiz":{"q":"加入催化劑對平衡常數的影響為何？","options":["變大","變小","不改變"],"answer":2,"explain":"在溫度固定時，催化劑改變反應速率，不改變平衡常數。"}},
{"id":"chem-elective-acidbase","title":"選修化學：酸鹼與緩衝","subject":"chemistry","level":"elective","icon":"pH","color":"#fff0e4","description":"pH、酸鹼平衡與緩衝溶液。","concept":"稀水溶液常以 pH=−log[H⁺] 表示酸度。緩衝溶液含有弱酸及其共軛鹼（或弱鹼及其共軛酸），能減少少量酸鹼加入時的 pH 變化。","formula":"pH=−log₁₀[H⁺]。","example":"若 [H⁺]=1×10⁻³ M，則 pH=3。","tool":"calculator","quiz":{"q":"[H⁺]=10⁻⁵ M 時，pH 為何？","options":["5","−5","10"],"answer":0,"explain":"pH=−log₁₀(10⁻⁵)=5。"}},
{"id":"chem-elective-redox","title":"選修化學：氧化還原與電化學","subject":"chemistry","level":"elective","icon":"🔌","color":"#fff0e4","description":"氧化數、電子轉移與電池。","concept":"氧化是失去電子、氧化數上升；還原是得到電子、氧化數下降。原電池將自發氧化還原反應的化學能轉為電能。","formula":"陽極發生氧化；陰極發生還原。","example":"Zn → Zn²⁺ + 2e⁻ 中，鋅失去電子，氧化數由 0 上升至 +2，因此鋅被氧化。","tool":"chemistry","quiz":{"q":"還原反應的特徵是什麼？","options":["失去電子","得到電子","氧化數一定上升"],"answer":1,"explain":"還原表示得到電子，氧化數下降。"}},
{"id":"biology-genetics","title":"生物：遺傳與基因表現","subject":"biology","level":"elective","icon":"🧬","color":"#e2f7eb","description":"DNA、RNA、蛋白質與孟德爾遺傳。","concept":"DNA 保存遺傳資訊；轉錄將 DNA 資訊製成 RNA，轉譯則由核糖體依 mRNA 密碼子排列胺基酸形成多肽。基因型與環境共同影響表現型。","formula":"DNA →（轉錄）RNA →（轉譯）蛋白質。","example":"若某性狀由完全顯性等位基因 A 控制，Aa 個體通常表現顯性性狀，但仍會將 A 或 a 其中一個傳給配子。","tool":"academy","quiz":{"q":"蛋白質合成的轉譯主要在哪裡進行？","options":["核糖體","高基氏體","細胞膜"],"answer":0,"explain":"核糖體讀取 mRNA 密碼子並組裝胺基酸。"}},
{"id":"biology-evolution","title":"生物：演化與天擇","subject":"biology","level":"elective","icon":"🌱","color":"#e2f7eb","description":"族群變異、遺傳與自然選擇。","concept":"自然選擇作用於個體的可遺傳差異；若某些性狀在特定環境下提高繁殖成功率，相關遺傳變異可能在族群中逐代增加。個體不會因為「需要」而主動演化。","formula":"可遺傳變異＋差異繁殖成功率 → 族群世代改變。","example":"細菌族群中若原本存在抗藥性變異，使用抗生素後，具抗性的細菌較可能存活並繁殖，族群中抗藥性比例可能增加。","tool":"academy","quiz":{"q":"自然選擇造成的演化主要發生在哪個層級？","options":["單一個體一生中改變","族群跨世代的遺傳組成改變","所有生物都朝同一方向進步"],"answer":1,"explain":"演化描述族群遺傳特徵跨世代的改變。"}},
{"id":"biology-ecology","title":"生物：生態系能量流動","subject":"biology","level":"elective","icon":"🌿","color":"#e2f7eb","description":"食物網、營養階層與物質循環。","concept":"能量由生產者進入消費者，沿食物鏈傳遞時有相當部分以熱散失；物質則可透過碳、氮等循環在生物與環境間移動。","formula":"能量流動單向；物質可循環。","example":"草→兔→狐狸，草為生產者，兔為初級消費者，狐狸為次級消費者。","tool":"academy","quiz":{"q":"生態系中的能量流動通常有何特徵？","options":["可完全循環回生產者","單向傳遞並逐級散失","不受呼吸作用影響"],"answer":1,"explain":"能量在營養階層傳遞時有部分以熱散失，因此不能像物質一樣完全循環。"}},
{"id":"earth-plate","title":"地球科學：板塊構造","subject":"earth","level":"elective","icon":"🌋","color":"#ffe9df","description":"板塊邊界、地震與火山分布。","concept":"岩石圈板塊在軟流圈上方移動。聚合、張裂與錯動邊界會形成不同地形與地質現象；地震和火山常集中在板塊邊界，但並非所有火山都位於邊界。","formula":"聚合：碰撞／隱沒；張裂：新洋殼形成；錯動：水平剪切。","example":"海洋板塊隱沒到另一板塊下方，可能形成海溝與火山弧。","tool":"academy","quiz":{"q":"海洋板塊隱沒常與哪種地形組合有關？","options":["海溝與火山弧","只有沙丘","只有河口三角洲"],"answer":0,"explain":"隱沒作用常形成海溝，含水物質促進上覆地函部分熔融，可能形成火山弧。"}},
{"id":"earth-weather","title":"地球科學：天氣圖與鋒面","subject":"earth","level":"elective","icon":"🌦","color":"#ffe9df","description":"氣團、冷暖鋒與降水。","concept":"鋒面是不同性質氣團交界。冷鋒通常由冷氣團推進並迫使暖空氣快速抬升；暖鋒則常有較緩慢的抬升與較廣範圍的層狀雲降水。實際天氣仍需結合地形與水氣判斷。","formula":"空氣抬升冷卻 → 水氣凝結 → 雲與降水。","example":"冷鋒通過時，常見風向、氣溫改變，並可能出現短時較強降雨。","tool":"academy","quiz":{"q":"鋒面降水常見的直接原因是什麼？","options":["空氣下沉增溫","空氣抬升冷卻凝結","地表完全沒有水氣"],"answer":1,"explain":"鋒面附近暖濕空氣被迫抬升，冷卻後水氣凝結形成雲與降水。"}},
{"id":"earth-stars","title":"地球科學：恆星與宇宙","subject":"earth","level":"elective","icon":"🌌","color":"#ffe9df","description":"恆星亮度、光譜與宇宙膨脹。","concept":"恆星的顏色與表面溫度相關，藍白色恆星表面通常比紅色恆星熱。光譜可提供溫度、化學組成與相對運動資訊；遙遠星系光譜紅移是宇宙膨脹的重要觀測證據之一。","formula":"波長增加為紅移；波長縮短為藍移。","example":"若某星系光譜線相對實驗室波長往較長波長移動，稱為紅移。","tool":"academy","quiz":{"q":"恆星光譜線往較長波長移動稱為什麼？","options":["藍移","紅移","全反射"],"answer":1,"explain":"波長增加、光譜線向紅端移動稱為紅移。"}}
];
function renderLessons(filter='all'){const grid=$('lessonGrid');if(!grid)return;const done=new Set(readLessons());const basics=lessonData.filter(l=>filter==='all'||l.subject===filter||l.level===filter||(filter==='elective'&&l.level==='elective')).map(l=>({...l,cardType:'lesson'}));const electives=(typeof chapterData!=='undefined'?chapterData:[]).filter(c=>(filter==='all'||filter==='elective'&&c.level==='elective'||c.subject===filter||c.level===filter)).map(c=>({id:c.id,title:c.title,subject:c.subject,level:c.level,icon:c.icon,color:({math:'#ece9ff',chemistry:'#fff0e4',physics:'#e1f8fa',biology:'#e2f7eb',earth:'#ffe9df'})[c.subject]||'#e8eaf2',description:c.detail[0],cardType:'chapter'}));const list=[...basics,...electives];grid.innerHTML=list.map(l=>`<article class="lesson-card"><div class="lesson-icon" style="background:${l.color}">${l.icon}</div><span class="eyebrow">${({math:'數學',chemistry:'化學',physics:'物理',biology:'生物',earth:'地球科學'})[l.subject]||l.subject} · ${l.level==='middle'?'國中基礎':l.level==='elective'?'選修／進階':'高中進階'}</span><h3>${l.title}</h3><p>${l.description}</p><div class="lesson-meta"><span>${done.has(l.id)?'✓ 已完成':'觀念 · 範例 · 進階挑戰'}</span>${l.cardType==='chapter'?`<button data-open-elective-chapter="${l.id}">開始學習 ↗</button>`:`<button data-open-lesson="${l.id}">開始學習 ↗</button>`}</div></article>`).join('');$$('[data-open-lesson]',grid).forEach(b=>b.addEventListener('click',()=>{window.location.href=(document.body.dataset.root||'./')+'pages/lessons/'+b.dataset.openLesson+'.html'}));$$('[data-open-elective-chapter]',grid).forEach(b=>b.addEventListener('click',()=>openChapter(b.dataset.openElectiveChapter)))}
$$('[data-subject]').forEach(b=>b.addEventListener('click',()=>{$$('[data-subject]').forEach(x=>x.classList.toggle('active',x===b));renderLessons(b.dataset.subject)}));
function openLesson(id){const l=lessonData.find(x=>x.id===id);if(!l)return;$('lessonReader').classList.remove('hidden');$('lessonContent').innerHTML=`<span class="eyebrow">${l.subject.toUpperCase()} / LESSON</span><h2>${l.title}</h2><p>${l.description}</p><h3>一、核心觀念</h3><p>${l.concept}</p><h3>二、重要公式</h3><div class="lesson-example"><strong>${l.formula}</strong></div><h3>三、範例解析</h3><div class="lesson-example">${l.example}</div><button class="btn btn-secondary" id="openLessonTool">開啟對應工具 ↗</button><div class="quiz-box"><span class="eyebrow">QUICK CHECK</span><h3>四、試試看</h3><p>${l.quiz.q}</p><div class="quiz-options">${l.quiz.options.map((o,i)=>`<button class="quiz-option" data-answer="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div><div id="quizFeedback" class="muted">選擇一個答案查看解析。</div></div>`;$$('[data-answer]',$('lessonContent')).forEach(b=>b.addEventListener('click',()=>{const correct=Number(b.dataset.answer)===l.quiz.answer;$$('[data-answer]',$('lessonContent')).forEach(x=>{x.disabled=true;if(Number(x.dataset.answer)===l.quiz.answer)x.classList.add('correct')});if(!correct)b.classList.add('incorrect');$('quizFeedback').innerHTML=`<strong style="color:${correct?'#1caa7c':'#d84b68'}">${correct?'答對了！':'再想一想。'}</strong> ${l.quiz.explain}`;if(correct){markLesson(l.id);toast('已完成教學單元！')}}));$('openLessonTool').addEventListener('click',()=>navigate(l.tool));$('lessonReader').scrollIntoView({behavior:'smooth',block:'start'})}
$('closeLesson').addEventListener('click',()=>{$('lessonReader').classList.add('hidden');$('lessonReader').scrollIntoView({behavior:'smooth',block:'start'})});
function renderHistory(){const box=$('historyList');if(!box)return;const q=($('historySearch')?.value||'').toLowerCase();const list=readHistory().filter(h=>(h.type+h.expression+h.result).toLowerCase().includes(q));if(!list.length){box.innerHTML='<div class="empty-state"><strong>目前沒有符合的紀錄</strong>開始使用計算工具，結果就會自動出現在這裡。</div>';return}box.innerHTML=list.map(h=>`<article class="history-entry"><div class="history-type">◷</div><div class="history-main"><strong>${escapeHtml(h.type)} · ${escapeHtml(h.result)}</strong><p>${escapeHtml(h.expression)}</p></div><time>${new Date(h.time).toLocaleString('zh-TW',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</time><button data-copy-history="${String(h.id)}">複製</button></article>`).join('');$$('[data-copy-history]',box).forEach(b=>b.addEventListener('click',async()=>{const h=readHistory().find(x=>String(x.id)===b.dataset.copyHistory);if(!h)return;try{await navigator.clipboard.writeText(`${h.type}\n${h.expression}\n${h.result}`);toast('已複製紀錄')}catch{toast('瀏覽器不允許複製，請手動選取文字')}}))}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('historySearch').addEventListener('input',renderHistory);
$('clearHistory').addEventListener('click',()=>{if(confirm('確定要清除全部計算紀錄嗎？')){localStorage.removeItem(STORAGE.history);renderHistory();updateDashboard();toast('計算紀錄已清除')}});
$('exportHistory').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(readHistory(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='world-law-history.json';a.click();URL.revokeObjectURL(url);toast('已匯出 JSON 檔案')});
function runSelfTests(){const tests=[['加法',()=>safeEval('6+7')===13],['次方',()=>safeEval('2^3')===8],['平方根',()=>safeEval('sqrt(81)')===9],['化學配平',()=>balanceChemical('H2 + O2 -> H2O').balanced==='2H2 + O2 → 2H2O'],['二次方程式係數邏輯',()=>Math.abs((-(-5)+Math.sqrt(25-24))/2-3)<1e-9]];const failed=[];tests.forEach(([name,fn])=>{try{if(!fn())failed.push(name)}catch{failed.push(name)}});console.info(`[理科解析：萬物的法則之眼 自我檢查] ${tests.length-failed.length}/${tests.length} passed`,failed);if(failed.length)console.warn('測試未通過：',failed)}

